package db

import (
	"crypto/rand"
	"database/sql/driver"
	"encoding/json"
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/oklog/ulid/v2"
)

var (
	idMu      sync.Mutex
	idEntropy = ulid.Monotonic(rand.Reader, 0)
)

// NewID returns a new lowercase ULID. IDs generated by one process are
// strictly increasing, so they sort by creation order.
func NewID() string {
	idMu.Lock()
	id := ulid.MustNew(ulid.Timestamp(time.Now()), idEntropy)
	idMu.Unlock()
	return strings.ToLower(id.String())
}

// IDTime extracts the creation time encoded in an id created by NewID.
func IDTime(id string) (time.Time, error) {
	u, err := ulid.ParseStrict(strings.ToUpper(id))
	if err != nil {
		return time.Time{}, err
	}
	return ulid.Time(u.Time()).UTC(), nil
}

// ValidID reports whether s looks like an id created by NewID.
func ValidID(s string) bool {
	if len(s) != ulid.EncodedSize {
		return false
	}
	_, err := ulid.ParseStrict(strings.ToUpper(s))
	return err == nil
}

// JSON stores a Go value in a TEXT column as JSON. The zero value of T is
// written as JSON of the zero value (e.g. "null" for maps and slices, "{}" is
// not implied); NULL and empty strings scan into the zero value.
//
//	type Project struct {
//	    Settings db.JSON[ProjectSettings] `db:"settings"`
//	}
type JSON[T any] struct {
	V T
}

// NewJSON wraps v.
func NewJSON[T any](v T) JSON[T] { return JSON[T]{V: v} }

// Scan implements sql.Scanner.
func (j *JSON[T]) Scan(src any) error {
	var zero T
	j.V = zero
	var b []byte
	switch v := src.(type) {
	case nil:
		return nil
	case []byte:
		b = v
	case string:
		b = []byte(v)
	default:
		return fmt.Errorf("db.JSON: cannot scan %T", src)
	}
	if len(b) == 0 {
		return nil
	}
	if err := json.Unmarshal(b, &j.V); err != nil {
		return fmt.Errorf("db.JSON: %w", err)
	}
	return nil
}

// Value implements driver.Valuer.
func (j JSON[T]) Value() (driver.Value, error) {
	b, err := json.Marshal(j.V)
	if err != nil {
		return nil, fmt.Errorf("db.JSON: %w", err)
	}
	return string(b), nil
}

// MarshalJSON makes JSON[T] transparent in API responses.
func (j JSON[T]) MarshalJSON() ([]byte, error) { return json.Marshal(j.V) }

// UnmarshalJSON makes JSON[T] transparent in API requests.
func (j *JSON[T]) UnmarshalJSON(b []byte) error { return json.Unmarshal(b, &j.V) }

// MustJSON marshals v for use as a query argument of a JSON column. It panics
// only if v cannot be marshalled, which is a programming error.
func MustJSON(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		panic(fmt.Sprintf("db.MustJSON: %v", err))
	}
	return string(b)
}

// NullString returns nil for "" so optional foreign keys are stored as NULL.
func NullString(s string) any {
	if s == "" {
		return nil
	}
	return s
}

// NullTime returns nil for the zero time.
func NullTime(t time.Time) any {
	if t.IsZero() {
		return nil
	}
	return t.UTC()
}
